class Solution {
    static const long long MOD = 1000000007LL;
    vector<long long> fact, inv_fact;

    long long power(long long b, long long e) {
        long long r = 1;
        b %= MOD;
        while (e > 0) {
            if (e & 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }

public:
    int countAnagrams(string s) {
        int n = s.size();
        fact.resize(n + 1);
        inv_fact.resize(n + 1);
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        inv_fact[n] = power(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) inv_fact[i - 1] = inv_fact[i] * i % MOD;

        long long ans = 1;
        int cnt[26];
        int i = 0;
        while (i <= n) {
            if (i == n || s[i] == ' ') {
                // word ended at i; process [start, i)
                i++;
                continue;
            }
            int start = i;
            while (i < n && s[i] != ' ') i++;
            int len = i - start;
            for (int k = 0; k < 26; k++) cnt[k] = 0;
            for (int j = start; j < start + len; j++) cnt[s[j] - 'a']++;
            long long term = fact[len];
            for (int k = 0; k < 26; k++)
                if (cnt[k] > 1) term = term * inv_fact[cnt[k]] % MOD;
            ans = ans * term % MOD;
            i++; // skip space
        }
        return (int)ans;
    }
};
